session_start();require_once '../includes/koneksi.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id){$_SESSION['flash']=['type'=>'error','message'=>'ID anggota tidak valid.'];header('Location: list.php');exit;}try{$stmt=$pdo->prepare('DELETE FROM anggota WHERE id=:id');$stmt->execute([':id'=>$id]);$_SESSION['flash']=$stmt->rowCount()?['type'=>'success','message'=>'Data anggota berhasil dihapus.']:['type'=>'error','message'=>'Data anggota tidak ditemukan.'];}catch(PDOException $e){$_SESSION['flash']=['type'=>'error','message'=>'Data anggota gagal dihapus.'];}header('Location: list.php');exit;
